<?php namespace BinerMail;
class Auth{public static function user():?array{if(empty($_SESSION['user_id']))return null;$s=Database::pdo()->prepare('SELECT * FROM bm_users WHERE id=? AND active=1');$s->execute([$_SESSION['user_id']]);return $s->fetch()?:null;}public static function login(array $u):void{session_regenerate_id(true);$_SESSION['user_id']=$u['id'];}public static function logout():void{$_SESSION=[];session_destroy();}public static function require():array{$u=self::user();if(!$u)redirect('/login.php');return $u;}public static function admin():array{$u=self::require();if(!$u['is_admin']){http_response_code(403);exit('Forbidden');}return $u;}}
